const ENHANCE_SOURCE_BUNDLE_REL: &str = "app/__shell/conventions.md";

fn settings_has_worklist_guard_hook(settings_path: &Path) -> bool {
    let content = match std::fs::read_to_string(settings_path) {
        Ok(s) => s,
        Err(_) => return false,
    };
    let value: serde_json::Value = match serde_json::from_str(&content) {
        Ok(v) => v,
        Err(_) => return false,
    };
    value
        .get("hooks")
        .and_then(|h| h.get("PreToolUse"))
        .and_then(|p| p.as_array())
        .map(|arr| {
            arr.iter().any(|entry| {
                entry
                    .get("hooks")
                    .and_then(|h| h.as_array())
                    .map(|hs| {
                        hs.iter().any(|h| {
                            h.get("command")
                                .and_then(|c| c.as_str())
                                .map(|s| s.contains("claude-worklist-guard.py"))
                                .unwrap_or(false)
                        })
                    })
                    .unwrap_or(false)
            })
        })
        .unwrap_or(false)
}

// True iff settings.json registers the permission-menu hook on all four events
// it needs: PermissionRequest (surface), PostToolUse + PermissionDenied (clear),
// and PreToolUse (AskUserQuestion surface). Mirrors
// settings_has_worklist_guard_hook; requiring the full set means a partial or
// pre-cutover (2-event) install is correctly flagged as still needing Setup.
// issue-217: prune legacy generic-name installed Claude hooks once no
// settings source references them. Runs at Bram startup — before any
// Claude session this Bram spawns, so no hook snapshot from a
// Bram-managed session can still point at the pruned paths. (A session
// launched outside Bram against a half-migrated project is the accepted
// residual edge; re-running Setup restores the transitional copy.)
// Containment is exact: the new commands contain "hooks/claude-…", which
// does not match the legacy "hooks/worklist-guard.py" needles.
//
// issue-227: Claude Code merges hook config from THREE sources — the
// project settings.json, the project settings.local.json, and the
// user-global ~/.claude/settings.json — and a legacy reference in ANY of
// them keeps the shim load-bearing. Andrew's 2.24→2.26 upgrade proved the
// failure mode: a pre-#217 entry in his global file, satisfied by the shim
// for weeks, then a prune keyed off the project file alone deleted the
// shim and every Write/Edit in every project was blocked by hook spawn
// failure. Bram never rewrites the global or local file (not ours), so a
// stale non-project reference holds the prune back and is surfaced as a
// named drift warning instead (stderr here; Setup result via
// stale_legacy_hook_reference_warnings).

const LEGACY_CLAUDE_HOOKS: [(&str, &str); 2] = [
    (".claude/hooks/worklist-guard.py", "hooks/worklist-guard.py"),
    (
        ".claude/hooks/permission-menu-hook.py",
        "hooks/permission-menu-hook.py",
    ),
];

// The three settings sources Claude Code merges hook config from, as
// (display label, path). Label doubles as the user-facing name in drift
// warnings, so keep it recognizable as a file path.
fn claude_settings_sources(proj: &Path) -> Vec<(String, PathBuf)> {
    let mut v = vec![
        (
            format!("{}/{}", proj.display(), ENHANCE_SETTINGS_REL),
            proj.join(ENHANCE_SETTINGS_REL),
        ),
        (
            format!("{}/.claude/settings.local.json", proj.display()),
            proj.join(".claude/settings.local.json"),
        ),
    ];
    if let Some(home) = home_dir() {
        v.push((
            "~/.claude/settings.json".to_string(),
            home.join(".claude").join("settings.json"),
        ));
    }
    v
}

// Pure core, testable without a filesystem: which source labels reference
// the needle?
fn legacy_hook_referencing_sources(sources: &[(String, String)], needle: &str) -> Vec<String> {
    sources
        .iter()
        .filter(|(_, text)| text.contains(needle))
        .map(|(label, _)| label.clone())
        .collect()
}

fn prune_legacy_claude_hooks(proj: &Path) {
    let sources: Vec<(String, String)> = claude_settings_sources(proj)
        .into_iter()
        .map(|(label, path)| (label, std::fs::read_to_string(&path).unwrap_or_default()))
        .collect();
    for (legacy_rel, needle) in LEGACY_CLAUDE_HOOKS {
        let path = proj.join(legacy_rel);
        if !path.exists() {
            continue;
        }
        let referencing = legacy_hook_referencing_sources(&sources, needle);
        if referencing.is_empty() {
            let _ = std::fs::remove_file(&path);
            eprintln!("[bram] pruned legacy hook {} (#217 migration)", legacy_rel);
        } else {
            eprintln!(
                "[bram] kept legacy hook {} — still referenced by {} (#227); update or remove that hook entry, then the shim can be pruned",
                legacy_rel,
                referencing.join(", ")
            );
        }
    }
}

// Setup-result drift warnings (issue-227): name every settings source Bram
// does not own that still references a retired legacy hook. The project
// settings.json is excluded — Setup itself migrates that file, so a stale
// reference there is fixed by the very Setup run that would report it.
fn stale_legacy_hook_reference_warnings(proj: &Path) -> Vec<String> {
    let sources: Vec<(String, String)> = claude_settings_sources(proj)
        .into_iter()
        .skip(1) // project settings.json is Setup-managed, not drift
        .map(|(label, path)| (label, std::fs::read_to_string(&path).unwrap_or_default()))
        .collect();
    let mut warnings = Vec::new();
    for (_, needle) in LEGACY_CLAUDE_HOOKS {
        for label in legacy_hook_referencing_sources(&sources, needle) {
            warnings.push(format!(
                "{} references {} (retired in #217) — update or remove that hook entry; the legacy shim stays until then",
                label, needle
            ));
        }
    }
    warnings
}

fn settings_has_permission_menu_hook(settings_path: &Path) -> bool {
    let content = match std::fs::read_to_string(settings_path) {
        Ok(s) => s,
        Err(_) => return false,
    };
    let value: serde_json::Value = match serde_json::from_str(&content) {
        Ok(v) => v,
        Err(_) => return false,
    };
    let event_has_menu_hook = |event: &str| -> bool {
        value
            .get("hooks")
            .and_then(|h| h.get(event))
            .and_then(|p| p.as_array())
            .map(|arr| {
                arr.iter().any(|entry| {
                    entry
                        .get("hooks")
                        .and_then(|h| h.as_array())
                        .map(|hs| {
                            hs.iter().any(|h| {
                                h.get("command")
                                    .and_then(|c| c.as_str())
                                    .map(|s| s.contains("claude-permission-menu-hook.py"))
                                    .unwrap_or(false)
                            })
                        })
                        .unwrap_or(false)
                })
            })
            .unwrap_or(false)
    };
    event_has_menu_hook("PermissionRequest")
        && event_has_menu_hook("PostToolUse")
        && event_has_menu_hook("PermissionDenied")
        && event_has_menu_hook("PreToolUse")
}

// Remove any PreToolUse hook entries whose `command` contains
// `proposal-guard.py` (the pre-rename script name, see bc3ee31). Hooks
// arrays emptied by the prune are dropped; entries with no remaining
// hooks are removed. Returns Ok(true) if anything was changed, Ok(false)
// if there was nothing to prune (or the file/JSON shape made it a no-op).
fn prune_proposal_guard_from_settings(settings_path: &Path) -> Result<bool, String> {
    let existing = match std::fs::read_to_string(settings_path) {
        Ok(s) => s,
        Err(_) => return Ok(false),
    };
    if existing.trim().is_empty() {
        return Ok(false);
    }
    let mut value: serde_json::Value = serde_json::from_str(&existing)
        .map_err(|e| format!("parse {}: {}", settings_path.display(), e))?;
    let Some(pre_arr) = value
        .get_mut("hooks")
        .and_then(|h| h.get_mut("PreToolUse"))
        .and_then(|p| p.as_array_mut())
    else {
        return Ok(false);
    };
    let mut changed = false;
    pre_arr.retain_mut(|entry| {
        let Some(hooks_arr) = entry.get_mut("hooks").and_then(|h| h.as_array_mut()) else {
            return true;
        };
        let before = hooks_arr.len();
        hooks_arr.retain(|h| {
            !h.get("command")
                .and_then(|c| c.as_str())
                .map(|s| s.contains("proposal-guard.py"))
                .unwrap_or(false)
        });
        if hooks_arr.len() != before {
            changed = true;
        }
        !hooks_arr.is_empty()
    });
    if !changed {
        return Ok(false);
    }
    let serialized = serde_json::to_string_pretty(&value)
        .map_err(|e| format!("serialize settings.json: {}", e))?;
    std::fs::write(settings_path, format!("{}\n", serialized))
        .map_err(|e| format!("write {}: {}", settings_path.display(), e))?;
    Ok(true)
}

fn merge_claude_curl_allowlist_into_settings(settings_path: &Path) -> Result<bool, String> {
    let existing = std::fs::read_to_string(settings_path).unwrap_or_default();
    let mut value: serde_json::Value = if existing.trim().is_empty() {
        serde_json::json!({})
    } else {
        serde_json::from_str(&existing)
            .map_err(|e| format!("parse {}: {}", settings_path.display(), e))?
    };
    if !value.is_object() {
        return Err(format!(
            "{} root is not a JSON object",
            settings_path.display()
        ));
    }
    let root = value.as_object_mut().unwrap();
    let permissions = root
        .entry("permissions".to_string())
        .or_insert_with(|| serde_json::json!({}));
    if !permissions.is_object() {
        return Err(format!(
            "{}: permissions is not a JSON object",
            settings_path.display()
        ));
    }
    let permissions_obj = permissions.as_object_mut().unwrap();
    let allow = permissions_obj
        .entry("allow".to_string())
        .or_insert_with(|| serde_json::json!([]));
    if !allow.is_array() {
        return Err(format!(
            "{}: permissions.allow is not a JSON array",
            settings_path.display()
        ));
    }
    let allow_arr = allow.as_array_mut().unwrap();
    let before = allow_arr.len();
    allow_arr.retain(|entry| {
        let Some(s) = entry.as_str() else {
            return true;
        };
        !(s.starts_with("Bash(curl -sS")
            && (s.contains("__worklist") || s.contains("__iterate") || s.contains("__enhance")))
    });
    let mut changed = allow_arr.len() != before;
    for pattern in CLAUDE_CURL_ALLOW_PATTERNS {
        if !allow_arr
            .iter()
            .any(|entry| entry.as_str() == Some(*pattern))
        {
            allow_arr.push(serde_json::Value::String((*pattern).to_string()));
            changed = true;
        }
    }
    if !changed {
        return Ok(false);
    }
    if let Some(parent) = settings_path.parent() {
        std::fs::create_dir_all(parent)
            .map_err(|e| format!("create {}: {}", parent.display(), e))?;
    }
    let serialized = serde_json::to_string_pretty(&value)
        .map_err(|e| format!("serialize settings.json: {}", e))?;
    std::fs::write(settings_path, format!("{}\n", serialized))
        .map_err(|e| format!("write {}: {}", settings_path.display(), e))?;
    Ok(true)
}

// Ensure settings.json contains exactly one PreToolUse hook entry whose
// command matches ENHANCE_HOOK_COMMAND for this platform, preserving
// other keys. Existing worklist-guard.py entries with a different
// command string (e.g. the pre-cfg-windows bare path on a Windows
// project that was set up before the py-launcher migration) are
// removed and the correct entry is appended. Returns Ok(true) if any
// change was made, Ok(false) if the settings already had the exact
// entry and nothing needed migrating.
fn merge_worklist_guard_into_settings(settings_path: &Path) -> Result<bool, String> {
    let existing = std::fs::read_to_string(settings_path).unwrap_or_default();
    let mut value: serde_json::Value = if existing.trim().is_empty() {
        serde_json::json!({})
    } else {
        serde_json::from_str(&existing)
            .map_err(|e| format!("parse {}: {}", settings_path.display(), e))?
    };
    if !value.is_object() {
        return Err(format!(
            "{} root is not a JSON object",
            settings_path.display()
        ));
    }
    let root = value.as_object_mut().unwrap();
    let hooks = root
        .entry("hooks".to_string())
        .or_insert_with(|| serde_json::json!({}));
    if !hooks.is_object() {
        return Err(format!(
            "{}: hooks is not a JSON object",
            settings_path.display()
        ));
    }
    let hooks_obj = hooks.as_object_mut().unwrap();
    let pre = hooks_obj
        .entry("PreToolUse".to_string())
        .or_insert_with(|| serde_json::json!([]));
    if !pre.is_array() {
        return Err(format!(
            "{}: hooks.PreToolUse is not a JSON array",
            settings_path.display()
        ));
    }
    let pre_arr = pre.as_array_mut().unwrap();

    // Drop worklist-guard.py entries whose command differs from the
    // current platform's ENHANCE_HOOK_COMMAND. Migrates an existing
    // bare-path Windows install to `py -3 ...` (and would also handle
    // the reverse if a project moved between platforms).
    let mut migrated = false;
    pre_arr.retain_mut(|entry| {
        let Some(hooks_arr) = entry.get_mut("hooks").and_then(|h| h.as_array_mut()) else {
            return true;
        };
        let before = hooks_arr.len();
        hooks_arr.retain(|h| {
            let Some(cmd) = h.get("command").and_then(|c| c.as_str()) else {
                return true;
            };
            !(cmd.contains("worklist-guard.py") && cmd != ENHANCE_HOOK_COMMAND)
        });
        if hooks_arr.len() != before {
            migrated = true;
        }
        !hooks_arr.is_empty()
    });

    let exact_present = pre_arr.iter().any(|entry| {
        entry
            .get("hooks")
            .and_then(|h| h.as_array())
            .map(|hs| {
                hs.iter().any(|h| {
                    h.get("command")
                        .and_then(|c| c.as_str())
                        .map(|s| s == ENHANCE_HOOK_COMMAND)
                        .unwrap_or(false)
                })
            })
            .unwrap_or(false)
    });
    if exact_present && !migrated {
        return Ok(false);
    }
    if !exact_present {
        pre_arr.push(serde_json::json!({
            "matcher": "Write|Edit",
            "hooks": [{
                "type": "command",
                "command": ENHANCE_HOOK_COMMAND,
            }]
        }));
    }
    if let Some(parent) = settings_path.parent() {
        std::fs::create_dir_all(parent)
            .map_err(|e| format!("create {}: {}", parent.display(), e))?;
    }
    let serialized = serde_json::to_string_pretty(&value)
        .map_err(|e| format!("serialize settings.json: {}", e))?;
    std::fs::write(settings_path, format!("{}\n", serialized))
        .map_err(|e| format!("write {}: {}", settings_path.display(), e))?;
    Ok(true)
}

// Ensure `hooks_obj[event]` contains an entry whose hooks[].command equals
// `command` (with `matcher`). Migrates a stale entry that carries `marker` in
// its command but a different command string (platform move / path rename).
// Returns true if it changed anything. Shared by the permission-menu-hook
// registration, which spans two event arrays.
fn merge_command_hook_into_event(
    hooks_obj: &mut serde_json::Map<String, serde_json::Value>,
    event: &str,
    matcher: &str,
    command: &str,
    marker: &str,
) -> bool {
    let arr_val = hooks_obj
        .entry(event.to_string())
        .or_insert_with(|| serde_json::json!([]));
    let Some(arr) = arr_val.as_array_mut() else {
        return false;
    };
    let mut migrated = false;
    arr.retain_mut(|entry| {
        let Some(hs) = entry.get_mut("hooks").and_then(|h| h.as_array_mut()) else {
            return true;
        };
        let before = hs.len();
        hs.retain(|h| {
            let Some(cmd) = h.get("command").and_then(|c| c.as_str()) else {
                return true;
            };
            !(cmd.contains(marker) && cmd != command)
        });
        if hs.len() != before {
            migrated = true;
        }
        !hs.is_empty()
    });
    let present = arr.iter().any(|entry| {
        entry
            .get("hooks")
            .and_then(|h| h.as_array())
            .map(|hs| {
                hs.iter().any(|h| {
                    h.get("command")
                        .and_then(|c| c.as_str())
                        .map(|s| s == command)
                        .unwrap_or(false)
                })
            })
            .unwrap_or(false)
    });
    if !present {
        arr.push(serde_json::json!({
            "matcher": matcher,
            "hooks": [{ "type": "command", "command": command }]
        }));
        return true;
    }
    migrated
}

// Register the permission-menu surfacing hook in settings.json: a
// PermissionRequest entry (surface the menu) and a PostToolUse entry (clear it
// when the prompt is answered). Matcher ".*" on both — PermissionRequest only
// fires when a dialog will show, and a live menu blocks the session so the next
// PostToolUse is the answer; catching every tool (incl. dynamic mcp__* names)
// beats missing one and stranding a menu. Idempotent + migration-tolerant,
// mirroring merge_worklist_guard_into_settings. Ok(true) if anything changed.
fn merge_permission_menu_hook_into_settings(settings_path: &Path) -> Result<bool, String> {
    let existing = std::fs::read_to_string(settings_path).unwrap_or_default();
    let mut value: serde_json::Value = if existing.trim().is_empty() {
        serde_json::json!({})
    } else {
        serde_json::from_str(&existing)
            .map_err(|e| format!("parse {}: {}", settings_path.display(), e))?
    };
    if !value.is_object() {
        return Err(format!(
            "{} root is not a JSON object",
            settings_path.display()
        ));
    }
    let root = value.as_object_mut().unwrap();
    let hooks = root
        .entry("hooks".to_string())
        .or_insert_with(|| serde_json::json!({}));
    if !hooks.is_object() {
        return Err(format!(
            "{}: hooks is not a JSON object",
            settings_path.display()
        ));
    }
    let hooks_obj = hooks.as_object_mut().unwrap();
    let marker = "permission-menu-hook.py";
    let mut changed = false;
    changed |= merge_command_hook_into_event(
        hooks_obj,
        "PermissionRequest",
        ".*",
        ENHANCE_MENU_HOOK_COMMAND,
        marker,
    );
    changed |= merge_command_hook_into_event(
        hooks_obj,
        "PostToolUse",
        ".*",
        ENHANCE_MENU_HOOK_COMMAND,
        marker,
    );
    // Claude Code emits PermissionDenied on No/Esc answers; Codex does not
    // have this hook event and handles denial clears from PTY cancel output.
    changed |= merge_command_hook_into_event(
        hooks_obj,
        "PermissionDenied",
        ".*",
        ENHANCE_MENU_HOOK_COMMAND,
        marker,
    );
    // Family B: AskUserQuestion arrives via PreToolUse (not PermissionRequest),
    // matcher scoped to that tool so it doesn't fire on every tool call.
    changed |= merge_command_hook_into_event(
        hooks_obj,
        "PreToolUse",
        "AskUserQuestion",
        ENHANCE_MENU_HOOK_COMMAND,
        marker,
    );
    if !changed {
        return Ok(false);
    }
    if let Some(parent) = settings_path.parent() {
        std::fs::create_dir_all(parent)
            .map_err(|e| format!("create {}: {}", parent.display(), e))?;
    }
    let serialized = serde_json::to_string_pretty(&value)
        .map_err(|e| format!("serialize settings.json: {}", e))?;
    std::fs::write(settings_path, format!("{}\n", serialized))
        .map_err(|e| format!("write {}: {}", settings_path.display(), e))?;
    Ok(true)
}

// Provider-aware Context tab. Claude shows the project-local import chain
// plus Claude-managed memory/hooks/settings. Codex shows the durable local
// Codex-side sources that shape behavior on this machine: config, project
// files, memories, and rules.

struct ContextFile {
    category: &'static str,
    path: PathBuf,
    display: String,
    kind: Option<&'static str>,
}

fn context_provider<R: tauri::Runtime>(
    app: &AppHandle<R>,
    preferred: Option<SessionProvider>,
) -> SessionProvider {
    preferred
        .or_else(|| current_provider(app))
        .unwrap_or(SessionProvider::Claude)
}

fn collect_claude_context_files<R: tauri::Runtime>(app: &AppHandle<R>) -> Vec<ContextFile> {
    let mut out: Vec<ContextFile> = Vec::new();
    let Some(proj_root) = project_root(Some(app)) else {
        return out;
    };

    let claude_md = proj_root.join("CLAUDE.md");
    if claude_md.exists() {
        out.push(ContextFile {
            category: "project",
            path: claude_md.clone(),
            display: "CLAUDE.md".to_string(),
            kind: Some("claude-md"),
        });
        if let Ok(content) = std::fs::read_to_string(&claude_md) {
            for line in content.lines() {
                let trimmed = line.trim();
                let import_path = match trimmed.strip_prefix('@') {
                    Some(p) if !p.is_empty() && !p.starts_with(char::is_whitespace) => p,
                    _ => continue,
                };
                let abs = proj_root.join(import_path);
                if abs.exists() {
                    out.push(ContextFile {
                        category: "project",
                        path: abs,
                        display: import_path.to_string(),
                        kind: Some("import"),
                    });
                }
            }
        }
    }

    if let Some(home) = home_dir() {
        let memory_dir = home
            .join(".claude")
            .join("projects")
            .join(encode_path_for_filename(&proj_root))
            .join("memory");
        if memory_dir.is_dir() {
            let mut paths: Vec<PathBuf> = std::fs::read_dir(&memory_dir)
                .into_iter()
                .flatten()
                .filter_map(Result::ok)
                .map(|e| e.path())
                .filter(|p| p.is_file())
                .collect();
            paths.sort();
            for path in paths {
                let display = path
                    .file_name()
                    .and_then(|n| n.to_str())
                    .unwrap_or("")
                    .to_string();
                out.push(ContextFile {
                    category: "memory",
                    path,
                    display,
                    kind: None,
                });
            }
        }
    }

    let hooks_dir = proj_root.join(".claude").join("hooks");
    if hooks_dir.is_dir() {
        let mut paths: Vec<PathBuf> = std::fs::read_dir(&hooks_dir)
            .into_iter()
            .flatten()
            .filter_map(Result::ok)
            .map(|e| e.path())
            .filter(|p| p.is_file())
            .collect();
        paths.sort();
        for path in paths {
            let display = path
                .file_name()
                .and_then(|n| n.to_str())
                .unwrap_or("")
                .to_string();
            out.push(ContextFile {
                category: "hooks",
                path,
                display,
                kind: None,
            });
        }
    }

    let claude_dir = proj_root.join(".claude");
    for name in ["settings.json", "settings.local.json"] {
        let path = claude_dir.join(name);
        if path.exists() {
            out.push(ContextFile {
                category: "settings",
                path,
                display: name.to_string(),
                kind: None,
            });
        }
    }

    out
}

